#!/bin/sh
# fmri-gym session: one line per run, in order.
set -e
FMRI_GYM_PATH=/home/guibertf/DBP/fmri-gym
DBP_MEG_PATH=/home/guibertf/DBP/dbp_meg
EYETRACKER_PATH=/home/guibertf/DBP/eyelink-track
SESSION_DIR=/home/guibertf/DBP/scheduler/data/sub-template/ses-01
SUBJECT=sub-template
RIG=configs/examples/rigs/laptop.json
SES=${1:-001}
#RUN
mkdir -p "$SESSION_DIR/blocks/01_eyetrack_calibration_meg" && (cd "$EYETRACKER_PATH" && . .venv/bin/activate && eyetrack_calibration --subject sub-template --session 01 --run 01 --photodiode --screen 1)  # scheduler: {"task": "eyetrack_calibration_meg", "duration_s": 180.0, "parameters": {"run": "next", "photodiode": true, "screen": 1}}
mkdir -p "$SESSION_DIR/blocks/02_meg_retinotopy" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-retinotopy" -s=template)  # scheduler: {"task": "meg_retinotopy", "duration_s": 155.379, "parameters": {"autostart": false, "button-device": "", "fullfield": false, "habituation": 20, "max-ecc": 8.4, "p": 467, "seed": 1, "shift": 0, "sound-gap-max": 12.0, "sound-gap-min": 8.0, "trials": 0, "verify": false, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/03_meg_arc" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-ARC" -s=template -run=1)  # scheduler: {"task": "meg_arc", "duration_s": 400.642, "parameters": {"autostart": false, "button-device": "", "fb": 350, "lead-in": 2000, "lead-out": 5000, "max-rt": 10000, "n": 0, "run": "next", "run-fb": 10000, "train": 5000, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/04_meg_intuitive_physics" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-Intuitive-Physics" -s=template)  # scheduler: {"task": "meg_intuitive_physics", "duration_s": 518.0, "parameters": {"autostart": false, "block-size": 4, "button-device": "", "instr": 4000, "iti": 1000, "iti-max": 1500, "movies": "stimuli/intuitive_physics", "n": 24, "resp": 2000, "run": 1, "seed": 1, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/05_meg_mental_rotation" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-Mental-Rotation" -s=template)  # scheduler: {"task": "meg_mental_rotation", "duration_s": 380.2, "parameters": {"autostart": false, "button-device": "", "fb": 500, "fb-delay": 600, "fb-delay-max": 1000, "iti": 1000, "iti-max": 1500, "max-rt": 6000, "n": 64, "run": 1, "seed": 1, "stim-width": 1024, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/06_eyetrack_calibration_meg" && (cd "$EYETRACKER_PATH" && . .venv/bin/activate && eyetrack_calibration --subject sub-template --session 01 --run 02 --photodiode --screen 1)  # scheduler: {"task": "eyetrack_calibration_meg", "duration_s": 180.0, "parameters": {"run": "next", "photodiode": true, "screen": 1}}
mkdir -p "$SESSION_DIR/blocks/07_wisconsin_card_sorting_task" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/Wisconsin-Card-Sorting-Task" -s=template)  # scheduler: {"task": "wisconsin_card_sorting_task", "duration_s": 510.8, "parameters": {"all-cards": false, "autostart": false, "button-device": "", "fb": 800, "fb-delay": 600, "fb-delay-max": 1000, "iti": 800, "iti-max": 1200, "max_duration": "", "maxrun": 10, "minrun": 6, "mouse": false, "n": 128, "resp-keys": "1,2,3,4", "seed": 1, "soa": 0, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/08_meg_spatial_working_memory" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-spatial-working-memory" -s=template)  # scheduler: {"task": "meg_spatial_working_memory", "duration_s": 437.0, "parameters": {"answer-offset-deg": 3.5, "autostart": false, "button-device": "", "delay": 1000, "delay-max": 1500, "fb": 500, "fb-delay": 600, "fb-delay-max": 1000, "iti": 1000, "iti-max": 1500, "max-rt": 2000, "n": 40, "pre": 500, "run": 1, "seed": 1, "square-deg": 1.2, "step": 1000, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/09_meg_visual_search" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-visual-search" -s=template)  # scheduler: {"task": "meg_visual_search", "duration_s": 389.0, "parameters": {"autostart": false, "button-device": "", "fb": 500, "fb-delay": 600, "fb-delay-max": 1000, "item-deg": 0.8, "iti": 1000, "iti-max": 1500, "max-rt": 2000, "n": 80, "run": 1, "search-height-deg": 9.0, "search-width-deg": 12.0, "seed": 1, "wait-trigger": false}}
mkdir -p "$SESSION_DIR/blocks/10_meg_theory_of_mind" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-theory-of-mind" -s=template)  # scheduler: {"task": "meg_theory_of_mind", "duration_s": 538.15, "parameters": {"autostart": false, "button-device": "", "fb": 500, "fb-delay": 600, "fb-delay-max": 1000, "iti": 1000, "iti-max": 1500, "max-rt": 4000, "practice": false, "seed": 1, "story": 10000, "text-deg": 0.8, "wait-trigger": false, "wrap-deg": 12.0}}
mkdir -p "$SESSION_DIR/blocks/11_eyetrack_calibration_meg" && (cd "$EYETRACKER_PATH" && . .venv/bin/activate && eyetrack_calibration --subject sub-template --session 01 --run 03 --photodiode --screen 1)  # scheduler: {"task": "eyetrack_calibration_meg", "duration_s": 180.0, "parameters": {"run": "next", "photodiode": true, "screen": 1}}
mkdir -p "$SESSION_DIR/blocks/12_meg_eye_movements" && (cd "$DBP_MEG_PATH" && "$DBP_MEG_PATH/bin/MEG-eye-movements" -s=template)  # scheduler: {"task": "meg_eye_movements", "duration_s": 359.806, "parameters": {"autostart": false, "blocks": "saccades,lines,circles,sines", "bridge": "127.0.0.1:5010", "button-device": "", "circle-cycles": 3, "edf": "em<SUBJECT>.edf", "eyelink-record": false, "fix-cross": true, "lines-repeats": 2, "pursuit-amplitude-deg": 0.0, "pursuit-fix-ms": 500, "pursuit-hold-ms": 200, "pursuit-speed-deg": 10.0, "sacc-dwell-max-ms": 1500, "sacc-dwell-min-ms": 1000, "sacc-grid-scale": 0.7, "sacc-passes": 6, "seed": 1, "sine-cycles": 8, "sine-freq-hz": 0.25, "tracker-host": ""}}
(cd "$FMRI_GYM_PATH" && uv run fmri-play --curriculum configs/curricula/rushhour/all.json --subject "$SUBJECT" --ses "$SES" --run 1 --rig "$RIG" --duration 715 --resume)
(cd "$FMRI_GYM_PATH" && uv run fmri-play --curriculum configs/curricula/aigamestore/game1.json --subject "$SUBJECT" --ses "$SES" --run 1 --rig "$RIG" --duration 595 --resume)
(cd "$FMRI_GYM_PATH" && uv run fmri-play --curriculum configs/curricula/aigamestore/game4.json --subject "$SUBJECT" --ses "$SES" --run 1 --rig "$RIG" --duration 895 --resume)
